}

function canManageHolidayActivation(userRole) {
  return ADMIN_ROLES.includes(normalizeRole(userRole?.role || userRole));
}

const ORG_STRUCTURE_ROLES = ["admin", "ceo", "hr"];
const NOTES_VIEW_ROLES = ["hr", "admin", "ceo"];
const NOTES_WRITE_ROLES = ["tl", "op", "quality", "hr", "admin", "ceo", "rtm"];
const QUALITY_NOTES_VIEW_ROLES = ["hr", "admin", "ceo", "quality", "rtm", "tl", "op"];
const QUALITY_NOTES_WRITE_ROLES = ["quality", "tl", "op", "hr", "admin", "ceo", "rtm"];
const EQUIPMENT_ALL_ROLES = ["it", "hr", "admin", "ceo"];
const EQUIPMENT_UNIT_ROLES = ["op"];
const DASHBOARD_PAYROLL_ROLES = ["finance", "hr", "admin", "ceo"];
const DASHBOARD_FULL_ROLES = ["tl", "op", "hr", "admin", "ceo", "finance", "rtm", "quality"];

function canManageOrgStructure(userRole) {
  return perm("manageOrgStructure", userRole, () => ORG_STRUCTURE_ROLES.includes(userRole?.role));
}

function canViewOrgFull(userRole) {
  return perm("viewOrgFull", userRole, () =>
    MANAGE_ROLES.includes(userRole?.role) ||
    ALL_UNIT_ROLES.includes(userRole?.role) ||
    ["rtm", "quality"].includes(userRole?.role)
  );
}

function canViewOrgScoped(userRole) {
  return ["agent", "office_assistant", "tl", "op"].includes(userRole?.role);
}

function canViewOrgAgentScope(userRole) {
  return canViewOrgScoped(userRole);
}

function canManageEmployees(userRole) {
  return perm("manageEmployees", userRole, () => MANAGE_ROLES.includes(userRole?.role));
}

function canEditEmployeeRecord(userRole, emp) {
  if (!emp) return false;
  return perm("editEmployeeRecord", userRole, () => {
    if (MANAGE_ROLES.includes(userRole?.role)) return true;
    if (userRole?.role === "tl" || userRole?.role === "op") return false;
    return false;
  });
}

function canViewEmployeeNotes(userRole) {
  return perm("viewEmployeeNotes", userRole, () => NOTES_VIEW_ROLES.includes(userRole?.role));
}

function canWriteEmployeeNotes(userRole) {
  return perm("writeEmployeeNotes", userRole, () => NOTES_WRITE_ROLES.includes(userRole?.role));
}

function canViewQualityNotes(userRole) {
  return perm("viewQualityNotes", userRole, () => QUALITY_NOTES_VIEW_ROLES.includes(userRole?.role));
}

function canWriteQualityNotes(userRole) {
  return perm("writeQualityNotes", userRole, () => QUALITY_NOTES_WRITE_ROLES.includes(userRole?.role));
}

function canManageQualityNote(userRole, note, username) {
  if (!note) return false;
  const role = userRole?.role;
  if (["hr", "admin", "ceo"].includes(role)) return true;
  if (role === "quality" && String(note.authorUsername || "").toLowerCase() === String(username || "").toLowerCase()) {
    return true;
  }
  return false;
}

function canViewEmployeeDirectory(userRole) {
  return perm("viewEmployeeDirectory", userRole, () => hasAppAccess(userRole));
}

function canOpenEmployeeCard(userRole, emp) {
  if (!emp) return false;
  if (canManageEmployees(userRole)) return true;
  if (userRole?.employeeId && emp.id === userRole.employeeId) return true;
  if (userRole?.role === "tl" || userRole?.role === "op") return false;
  if (SELF_SCOPED_ROLES.includes(userRole?.role)) return false;
  return canAccessEmployee(userRole, emp);
}

function canExportSales(userRole) {
  if (!userRole) return false;
  return perm("exportSales", userRole, () => {
    return ["quality", "rtm", "ceo", "admin"].includes(normalizeRole(userRole.role));
  });
}

function canApproveSales(userRole) {
  return perm("approveSales", userRole, () => {
    const role = normalizeRole(userRole?.role);
    return ["quality", "rtm", "admin", "ceo", "hr"].includes(role);
  });
}

function canViewDashboardUnits(userRole) {
  return perm("viewDashboardUnits", userRole, () =>
    ["hr", "rtm", "admin", "ceo", "quality"].includes(userRole?.role)
  );
}

function canViewTeamDashboard(userRole) {
  return perm("viewTeamDashboard", userRole, () => canViewSales(userRole));
}

function canIssueEquipment(userRole) {
  return perm("issueEquipment", userRole, () => EQUIPMENT_ALL_ROLES.includes(userRole?.role));
}

function canViewEquipmentAll(userRole) {
  return perm("viewEquipmentAll", userRole, () => EQUIPMENT_ALL_ROLES.includes(userRole?.role));
}

function canViewEquipmentUnit(userRole) {
  return perm("viewEquipmentUnit", userRole, () => userRole?.role === "op");
}

function canViewEquipment(userRole) {
  if (canViewEquipmentAll(userRole) || canViewEquipmentUnit(userRole)) return true;
  return perm("viewEquipment", userRole, () => {
    if (userRole?.role === "finance") return false;
    return (ROLE_RANK[userRole?.role] || 0) >= ROLE_RANK.agent;
  });
}

function canViewEquipmentInventory(userRole) {
  return canViewEquipmentAll(userRole) || canViewEquipmentUnit(userRole);
}

function canViewEmployeeNationality(userRole, targetEmp) {
  if (targetEmp && userRole?.employeeId && userRole.employeeId === targetEmp.id) return true;
  return perm("viewEmployeeNationality", userRole, () => MANAGE_ROLES.includes(userRole?.role));
}

function canViewEmployeeNationalityGlobal(userRole) {
  return perm("viewEmployeeNationality", userRole, () => MANAGE_ROLES.includes(userRole?.role));
}

function canViewEmployeeCompliance(userRole, targetEmp) {
  if (!targetEmp) return false;
  if (userRole?.employeeId && userRole.employeeId === targetEmp.id) return true;
  return perm("viewEmployeeCompliance", userRole, () => MANAGE_ROLES.includes(userRole?.role));
}

function canViewEmployeeComplianceFilters(userRole) {
  return perm("viewEmployeeComplianceFilters", userRole, () => MANAGE_ROLES.includes(userRole?.role));
}

function canViewReports(userRole) {
  return perm("viewReports", userRole, () =>
    ["finance", "hr", "admin", "ceo"].includes(userRole?.role)
  );
}

function canManageAppUsersPerm(userRole, username) {
  const u = String(username || userRole?.username || "").trim().toLowerCase();
  return perm("manageAppUsers", userRole, () => canManageAppUsers(u));
}

function canViewSalesAdmin(userRole) {
  return perm("viewSalesAdmin", userRole, () => canManageSalesFieldPermissions(userRole));
}

function canViewSettingsSection(userRole, section) {
  const sectionKeys = {
    holidays: "settingsHolidays",
    session: "settingsSession",
    managingUnits: "settingsManagingUnits",
    hideOut: "settingsHideOut",
    sync: "settingsSync",
    theme: "settingsTheme",
    profilePhoto: "settingsProfilePhoto",
  };
  const key = sectionKeys[section];
  if (!key) return hasAppAccess(userRole);
  return perm(key, userRole, () => {
    const role = userRole?.role;
    if (section === "holidays") return MANAGE_ROLES.includes(role);
    if (section === "managingUnits") return MANAGE_ROLES.includes(role);
    if (section === "session") return MANAGE_ROLES.includes(role) || ADMIN_ROLES.includes(role);
    if (section === "hideOut") return MANAGE_ROLES.includes(role);
    if (section === "sync") return true;
    if (section === "theme") return true;
    if (section === "profilePhoto") return Boolean(userRole?.employeeId);
    return hasAppAccess(userRole);
  });
}

function canViewAgentPayslip(userRole, emp, adjustment) {
  if (!userRole || !emp) return false;
  if (canViewPayroll(userRole) && canAccessEmployee(userRole, emp)) return true;
  if (
    (userRole.role === "agent" || userRole.role === "office_assistant") &&
    userRole.employeeId === emp.id &&
    adjustment?.payslipVisibleToAgent === true
  ) {
    return true;
  }
  return false;
}

function canGrantSalesVisibility(userRole) {
  return perm("grantSalesVisibility", userRole, () =>
    ["op", "admin", "ceo", "hr", "rtm"].includes(userRole?.role)
  );
}

function canManageSalesFieldPermissions(userRole) {
  return perm("manageSalesFieldPermissions", userRole, () =>
    ["admin", "ceo", "rtm"].includes(userRole?.role)
  );
}
"}

{"content":"const { isLeadershipId } = require("./employee-ids");

const HS2_UNITS = new Set(["HS-2", "HS2-PT"]);

function parseCompanyContext(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "hs2" || raw === "hs-2") return "hs2";
  return "hangup";
}

function isHs2Unit(unit) {
  return HS2_UNITS.has(String(unit || "").trim());
}

function isHs2Team(team) {
  const t = String(team || "").trim().toUpperCase();
  return t === "HS2" || t.startsWith("HS2-") || t.includes("HS2");
}

function isHs2Id(id, unit) {
  const s = String(id || "").trim().toUpperCase();
  if (s.startsWith("HS2-")) return true;
  if (s.startsWith("PT-") && isHs2Unit(unit)) return true;
  return false;
}

function isInHs2Scope(emp) {
  if (!emp) return false;
  if (isHs2Id(emp.id, emp.unit)) return true;
  return isHs2Unit(emp.unit) || isHs2Team(emp.team);
}

function isHs2Tl(emp) {
  if (!emp) return false;
  if (!isLeadershipId(emp.id) || !String(emp.id).trim().toUpperCase().startsWith("TL")) {
    return false;
  }
  return isInHs2Scope(emp);
}

function isHiddenInHangupDefault(emp) {
  return isInHs2Scope(emp) || isHs2Tl(emp);
}

function filterEmployeesByCompany(employees, context) {
  const list = Array.isArray(employees) ? employees : [];
  if (parseCompanyContext(context) === "hs2") {
    return list.filter(isInHs2Scope);
  }
  return list.filter((e) => !isHiddenInHangupDefault(e));
}

function applyCompanyFilter(employees, context) {
  return filterEmployeesByCompany(employees, context);
}

function employeeInCompanyContext(emp, context) {
  if (!emp) return false;
  return filterEmployeesByCompany([emp], context).length > 0;
}

function isHs2SaleUnit(unit) {
  const u = String(unit || "").trim();
  return u === "HS-2" || u === "HS2" || isHs2Unit(u);
}

function resolveCompanyContextForUser(value, userRole) {
  const company = parseCompanyContext(value);
  if (company !== "hs2") return company;
  const roles = require("./roles");
  return roles.canManageHs2Company(userRole) ? "hs2" : "hangup";
}

function filterOrgUnitsForRole(orgUnits, userRole) {
  const roles = require("./roles");
  if (roles.canManageHs2Company(userRole)) return orgUnits || [];
  return (orgUnits || []).filter((u) => u !== "HS-2");
}

function filterUnitsListForRole(units, userRole) {
  const roles = require("./roles");
  if (roles.canManageHs2Company(userRole)) return units || [];
  return (units || []).filter((u) => {
    const t = String(u || "").trim();
    return t !== "HS-2" && t !== "HS2" && t !== "HS2-PT";
  });
}

function filterHs2SalesForRole(sales, userRole) {
  const roles = require("./roles");
  if (roles.canSeeHs2InSales(userRole)) return sales || [];
  return (sales || []).filter((s) => !isHs2SaleUnit(s.unit || s.formData?.unit));
}

module.exports = {
  parseCompanyContext,
  resolveCompanyContextForUser,
  filterEmployeesByCompany,
  applyCompanyFilter,
  employeeInCompanyContext,
  filterOrgUnitsForRole,
  filterUnitsListForRole,
  filterHs2SalesForRole,
  isHs2SaleUnit,
  isInHs2Scope,
  isHiddenInHangupDefault,
  isHs2Tl,
  isHs2Unit,
  isHs2Team,
  isHs2Id,
};
"}

{"content":"const WORKDAY_START_HOUR = 15;
const SAME_DAY_CUTOFF_HOUR = 12;

function todayLocal() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function isLateSameDayRequest(startDate) {
  if (startDate !== todayLocal()) return false;
  return new Date().getHours() >= SAME_DAY_CUTOFF_HOUR;
}

function validateRequestSubmit({
  requestKind,
  employeeId,
  startDate,
  endDate,
  actor,
  actorRole,
  targetEmp,
  forEmployeeId,
}) {
  const kind = String(requestKind || "annual").toLowerCase();
  const role = String(actorRole?.role || actorRole || "").toLowerCase();
  const empId = forEmployeeId || employeeId;
  const actorEmpId = actorRole?.employeeId || "";
  const isSelf =
    String(empId).toLowerCase() === String(actor || "").toLowerCase() ||
    (actorEmpId && String(empId) === String(actorEmpId));

  if (kind === "annual" && role === "agent") {
    if (!targetEmp?.employment_date) throw new Error("Cannot verify employment date. Annual leave not available.");
    const daysEmployed = (Date.now() - new Date(targetEmp.employment_date).getTime()) / (1000 * 60 * 60 * 24);
    if (daysEmployed < 180) throw new Error(`Annual leave requires 180+ days of employment. You have ${Math.floor(daysEmployed)} day(s).`);
  }

  if (kind === "annual" && !isSelf && !["hr", "admin", "ceo"].includes(role)) {
    throw new Error("Annual leave can only be requested for yourself.");
  }

  if (["unpaid", "medical", "same_day"].includes(kind) && ["tl", "op"].includes(role) && targetEmp) {
    if (targetEmp.team && actorRole?.team && targetEmp.team !== actorRole.team) {
      throw new Error("You can only request day off for agents on your team.");
    }
  }

  if (!startDate || !endDate) throw new Error("Start and end dates required.");
  if (endDate < startDate) throw new Error("End date must be on or after start date.");

  return {
    requestKind: kind,
    lateSubmission: isLateSameDayRequest(startDate),
    paidLeave: kind === "annual",
    tlRequested: ["tl", "op"].includes(role) && !isSelf,
  };
}

module.exports = {
  WORKDAY_START_HOUR,
  SAME_DAY_CUTOFF_HOUR,
  isLateSameDayRequest,
  validateRequestSubmit,
};
"}

{"content":"-- Phase 1: Rules content storage, IT requests, meeting requests, multiple TL/OP, HS2 separation

-- 1A. Rules content storage (editable per-company)
CREATE TABLE IF NOT EXISTS rules_content (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company text NOT NULL CHECK (company IN ('hangup', 'hs2')),
  section_key text NOT NULL,
  title text NOT NULL,
  content text NOT NULL,
  sort_order integer DEFAULT 0,
  updated_at timestamptz DEFAULT now(),
  updated_by text,
  UNIQUE(company, section_key)
);

-- 1B. Team TLs join table (multiple TLs per team)
CREATE TABLE IF NOT EXISTS team_tls (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id uuid NOT NULL REFERENCES org_teams(id) ON DELETE CASCADE,
  employee_id text NOT NULL,
  created_at timestamptz DEFAULT now(),
  UNIQUE(team_id, employee_id)
);

CREATE INDEX IF NOT EXISTS idx_team_tls_team ON team_tls(team_id);
CREATE INDEX IF NOT EXISTS idx_team_tls_employee ON team_tls(employee_id);

-- 1C. Unit OPs join table (multiple OPs per unit)
CREATE TABLE IF NOT EXISTS unit_ops (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  unit text NOT NULL,
  employee_id text NOT NULL,
  created_at timestamptz DEFAULT now(),
  UNIQUE(unit, employee_id)
);

CREATE INDEX IF NOT EXISTS idx_unit_ops_unit ON unit_ops(unit);
CREATE INDEX IF NOT EXISTS idx_unit_ops_employee ON unit_ops(employee_id);

-- Backfill: migrate existing single OP into unit_ops
INSERT INTO unit_ops (unit, employee_id)
SELECT unit, op_employee_id
FROM org_unit_managers
WHERE op_employee_id IS NOT NULL AND op_employee_id != ''
ON CONFLICT (unit, employee_id) DO NOTHING;

-- 1D. IT Requests table
CREATE TABLE IF NOT EXISTS it_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id text NOT NULL,
  title text NOT NULL,
  description text,
  category text NOT NULL DEFAULT 'other',
  urgency text NOT NULL DEFAULT 'normal',
  status text NOT NULL DEFAULT 'open',
  assigned_to text,
  created_by text NOT NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  resolved_at timestamptz,
  resolution_notes text,
  notes_hidden_from_requester text
);

CREATE INDEX IF NOT EXISTS idx_it_requests_employee ON it_requests(employee_id);
CREATE INDEX IF NOT EXISTS idx_it_requests_status ON it_requests(status);
CREATE INDEX IF NOT EXISTS idx_it_requests_assigned ON it_requests(assigned_to);

-- 1E. IT Request visibility scope
CREATE TABLE IF NOT EXISTS it_request_scope (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id uuid NOT NULL REFERENCES it_requests(id) ON DELETE CASCADE,
  scope_type text NOT NULL CHECK (scope_type IN ('employee', 'team', 'unit')),
  scope_value text NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_it_request_scope_request ON it_request_scope(request_id);

-- 1F. Meeting Requests table
CREATE TABLE IF NOT EXISTS meeting_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  description text,
  proposed_date date NOT NULL,
  proposed_time time NOT NULL,
  duration_minutes integer DEFAULT 30,
  requester_employee_id text NOT NULL,
  requester_role text NOT NULL,
  participants jsonb NOT NULL DEFAULT '[]',
  status text NOT NULL DEFAULT 'pending',
  reviewed_by text,
  review_notes text,
  rescheduled_proposal jsonb,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_meeting_requests_requester ON meeting_requests(requester_employee_id);
CREATE INDEX IF NOT EXISTS idx_meeting_requests_status ON meeting_requests(status);

-- 1G. Company column on position_rates (for HS2/Hangup separation)
ALTER TABLE position_rates
  ADD COLUMN IF NOT EXISTS company text DEFAULT 'hangup';

ALTER TABLE position_rate_monthly
  ADD COLUMN IF NOT EXISTS company text DEFAULT 'hangup';

-- 1H. Quality manager column on org_unit_managers
ALTER TABLE org_unit_managers
  ADD COLUMN IF NOT EXISTS quality_manager_id text;

-- 1I. Seed notification routing rules for new features
INSERT INTO notification_routing_rules (action_key, label, description, recipient_roles, recipient_usernames)
VALUES
  ('it_request_submitted', 'IT request submitted', 'When a new IT request is created', '{it,admin,ceo}', '{}'),
  ('it_request_assigned', 'IT request assigned', 'When an IT request is assigned to someone', '{it,admin,ceo}', '{}'),
  ('it_request_resolved', 'IT request resolved', 'When an IT request is marked resolved', '{it,admin,ceo,hr}', '{}'),
  ('meeting_request_submitted', 'Meeting request submitted', 'When a new meeting request is created', '{admin,ceo,hr}', '{}'),
  ('meeting_request_reviewed', 'Meeting request reviewed', 'When a meeting request is approved/rejected', '{admin,ceo,hr}', '{}')
ON CONFLICT (action_key) DO NOTHING;

-- Enable RLS on new tables
ALTER TABLE rules_content ENABLE ROW LEVEL SECURITY;
ALTER TABLE team_tls ENABLE ROW LEVEL SECURITY;
ALTER TABLE unit_ops ENABLE ROW LEVEL SECURITY;
ALTER TABLE it_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE it_request_scope ENABLE ROW LEVEL SECURITY;
ALTER TABLE meeting_requests ENABLE ROW LEVEL SECURITY;

-- Deny-all policies for all new tables (backend uses service role)
DO $$ BEGIN
  CREATE POLICY deny_all_rules_content ON rules_content FOR ALL TO anon, authenticated USING (false);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE POLICY deny_all_team_tls ON team_tls FOR ALL TO anon, authenticated USING (false);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE POLICY deny_all_unit_ops ON unit_ops FOR ALL TO anon, authenticated USING (false);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE POLICY deny_all_it_requests ON it_requests FOR ALL TO anon, authenticated USING (false);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE POLICY deny_all_it_request_scope ON it_request_scope FOR ALL TO anon, authenticated USING (false);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE POLICY deny_all_meeting_requests ON meeting_requests FOR ALL TO anon, authenticated USING (false);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
"}

{"content":"/**
 * App-wide permission catalog for admin Access Control.
 * Keys map to lib/roles.js can* helpers; defaults mirror v1.3.4 hardcoded behavior.
 */

const ROLE_RANK = {
  none: 0,
  agent: 1,
  office_assistant: 1,
  quality: 1,
  rtm: 1,
  public_relations: 1,
  tl: 2,
  op: 2,
  finance: 3,
  it: 4,
  hr: 4,
  admin: 5,
  ceo: 6,
};

const ROLE_ALIASES = {
  administrator: "admin",
  owner: "admin",
  superadmin: "admin",
  "chief executive": "ceo",
  "chief executive officer": "ceo",
  founder: "ceo",
  manager: "hr",
  "human resources": "hr",
  accountant: "finance",
  finances: "finance",
  payroll: "finance",
  "team lead": "tl",
  teamlead: "tl",
  "team leader": "tl",
  team_leader: "tl",
  leader: "tl",
  supervisor: "tl",
  employee: "agent",
  user: "agent",
  staff: "agent",
  "op manager": "op",
  operations: "op",
  "quality agent": "quality",
  qa: "quality",
  "office assistant": "office_assistant",
  assistant: "office_assistant",
  "public relations": "public_relations",
  pr: "public_relations",
  "information technology": "it",
  tech: "it",
};

function normalizeRole(role) {
  const raw = String(role || "").trim().toLowerCase();
  if (!raw) return "none";
  if (ROLE_RANK[raw] !== undefined && raw !== "none") return raw;
  if (ROLE_ALIASES[raw]) return ROLE_ALIASES[raw];
  return raw;
}

const MANAGEABLE_ROLES = [
  "agent",
  "office_assistant",
  "quality",
  "rtm",
  "public_relations",
  "tl",
  "op",
  "finance",
  "it",
  "hr",
  "admin",
  "ceo",
];

const ADMIN_ROLES = ["admin", "ceo"];
const MANAGE_ROLES = ["admin", "ceo", "hr"];
const ALL_UNIT_ROLES = ["admin", "ceo", "hr", "finance"];
const BONUS_VIEW_ROLES = [
  "agent",
  "office_assistant",
  "quality",
  "rtm",
  "tl",
  "op",
  "finance",
  "hr",
  "admin",
  "ceo",
];
const TRANSFER_BONUS_ROLES = ["tl", "op", "quality", "rtm"];
const BONUS_REQUEST_SUBMIT_ROLES = ["tl", "op", "admin", "hr", "quality", "rtm"];
const ORG_STRUCTURE_ROLES = ["admin", "ceo", "hr"];
const NOTES_VIEW_ROLES = ["hr", "admin", "ceo"];
const NOTES_WRITE_ROLES = ["tl", "op", "quality", "hr", "admin", "ceo", "rtm"];
const QUALITY_NOTES_VIEW_ROLES = ["hr", "admin", "ceo", "quality", "rtm", "tl", "op"];
const QUALITY_NOTES_WRITE_ROLES = ["quality", "tl", "op", "hr", "admin", "ceo", "rtm"];
const EQUIPMENT_ALL_ROLES = ["it", "hr", "admin", "ceo"];
const EQUIPMENT_UNIT_ROLES = ["op"];
const TL_OP_BONUS_TRANSFER_VIEW_ROLES = ["tl", "op", "hr", "admin", "ceo", "rtm"];
const REPORTS_VIEW_ROLES = ["finance", "hr", "admin", "ceo"];
const SALES_ADMIN_ROLES = ["admin", "ceo", "rtm"];
const DASHBOARD_PAYROLL_ROLES = ["finance", "hr", "admin", "ceo"];
const DASHBOARD_FULL_ROLES = ["tl", "op", "hr", "admin", "ceo", "finance", "rtm", "quality"];
const QUALITY_TICKET_ROLES = ["quality", "rtm", "admin", "ceo", "public_relations"];
const SUBMIT_SALES_ROLES = ["agent", "tl", "op", "admin", "ceo", "hr", "rtm", "quality", "public_relations"];
const FINANCE_ACCESS_USERS = ["mark", "phoebe", "raymond"];
const DASHBOARD_UNITS_ROLES = ["hr", "rtm", "admin", "ceo", "quality"];
const HS2_MANAGE_ROLES = ["admin", "ceo", "hr"];
