const { getSupabaseAdmin } = require("./supabase-client");
const { useSupabase } = require("./backend");

function db() {
  return getSupabaseAdmin();
}

function requireSupabase() {
  if (!useSupabase()) throw new Error("Requires DATA_BACKEND=supabase");
}

function mapRow(r) {
  return {
    id: r.id,
    employeeId: r.employee_id,
    title: r.title,
    description: r.description || "",
    category: r.category || "other",
    urgency: r.urgency || "normal",
    status: r.status || "open",
    assignedTo: r.assigned_to || "",
    unit: r.unit || "",
    createdBy: r.created_by,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
    resolvedAt: r.resolved_at || null,
    resolutionNotes: r.resolution_notes || "",
    notesHiddenFromRequester: r.notes_hidden_from_requester || "",
    // routing workflow
    approvedBy: r.approved_by || "",
    approvedAt: r.approved_at || null,
    deniedBy: r.denied_by || "",
    deniedAt: r.denied_at || null,
    denialReason: r.denial_reason || "",
    reassignedBy: r.reassigned_by || "",
    reassignedAt: r.reassigned_at || null,
  };
}

async function readItRequests(filters = {}) {
  requireSupabase();
  let query = db()
    .from("it_requests")
    .select("*, it_request_scope(*)")
    .order("created_at", { ascending: false });
  if (filters.employeeId) query = query.eq("employee_id", filters.employeeId);
  if (filters.assignedTo) query = query.eq("assigned_to", filters.assignedTo);
  if (filters.unit) query = query.eq("unit", filters.unit);
  if (filters.status) {
    const statuses = Array.isArray(filters.status) ? filters.status : [filters.status];
    query = query.in("status", statuses);
  }
  const { data, error } = await query;
  if (error) throw new Error(error.message);
  return (data || []).map((r) => ({
    ...mapRow(r),
    scope: (r.it_request_scope || []).map((s) => ({
      scopeType: s.scope_type,
      scopeValue: s.scope_value,
    })),
  }));
}

async function readItRequestById(id) {
  requireSupabase();
  const { data, error } = await db()
    .from("it_requests")
    .select("*, it_request_scope(*)")
    .eq("id", id)
    .single();
  if (error) throw new Error(error.message);
  return {
    ...mapRow(data),
    scope: (data.it_request_scope || []).map((s) => ({
      scopeType: s.scope_type,
      scopeValue: s.scope_value,
    })),
  };
}

async function createItRequest({ employeeId, title, description, category, urgency, createdBy, scope, unit }) {
  requireSupabase();
  const { data, error } = await db()
    .from("it_requests")
    .insert({
      employee_id: employeeId,
      title,
      description: description || null,
      category: category || "other",
      urgency: urgency || "normal",
      status: "open",
      created_by: createdBy,
      unit: unit || null,
    })
    .select()
    .single();
  if (error) throw new Error(error.message);
  if (scope && scope.length) {
    const scopeRows = scope.map((s) => ({
      request_id: data.id,
      scope_type: s.scopeType,
      scope_value: s.scopeValue,
    }));
    const { error: scopeErr } = await db().from("it_request_scope").insert(scopeRows);
    if (scopeErr) throw new Error(scopeErr.message);
  }
  return readItRequestById(data.id);
}

async function updateItRequest(id, patch) {
  requireSupabase();
  const now = new Date().toISOString();
  const row = { updated_at: now };
  if (patch.status !== undefined) row.status = patch.status;
  if (patch.assignedTo !== undefined) row.assigned_to = patch.assignedTo || null;
  if (patch.resolutionNotes !== undefined) row.resolution_notes = patch.resolutionNotes || null;
  if (patch.notesHiddenFromRequester !== undefined)
    row.notes_hidden_from_requester = patch.notesHiddenFromRequester || null;
  if (patch.status === "resolved" || patch.status === "closed") row.resolved_at = now;

  // routing actions
  if (patch.approvedBy !== undefined) {
    row.approved_by = patch.approvedBy || null;
    row.approved_at = patch.approvedBy ? now : null;
  }
  if (patch.deniedBy !== undefined) {
    row.denied_by = patch.deniedBy || null;
    row.denied_at = patch.deniedBy ? now : null;
    if (patch.denialReason !== undefined) row.denial_reason = patch.denialReason || null;
  }
  if (patch.reassignedBy !== undefined) {
    row.reassigned_by = patch.reassignedBy || null;
    row.reassigned_at = patch.reassignedBy ? now : null;
  }
  if (patch.unit !== undefined) row.unit = patch.unit || null;

  const { error } = await db().from("it_requests").update(row).eq("id", id);
  if (error) throw new Error(error.message);
  return readItRequestById(id);
}

async function deleteItRequest(id) {
  requireSupabase();
  const { error } = await db().from("it_requests").delete().eq("id", id);
  if (error) throw new Error(error.message);
}

/**
 * Returns all active app_users with role 'it' — used to populate the
 * assignee dropdown for IT ticket routing.
 */
async function readItUsers() {
  requireSupabase();
  const { data, error } = await db()
    .from("app_users")
    .select("username, employee_id, role, status")
    .eq("role", "it")
    .eq("status", "active");
  if (error) throw new Error(error.message);
  return (data || []).map((u) => ({
    username: u.username,
    employeeId: u.employee_id || "",
  }));
}

module.exports = {
  readItRequests,
  readItRequestById,
  createItRequest,
  updateItRequest,
  deleteItRequest,
  readItUsers,
};

const WORKDAY_START_HOUR = 15;
const SAME_DAY_CUTOFF_HOUR = 12;

/** Valid day fractions: 1 = full day, 0.5 = half-day, 0.25 = quarter-day. */
const VALID_FRACTIONS = [1, 0.5, 0.25];
const FRACTION_LABELS = { 1: "Full day", 0.5: "Half day", 0.25: "Quarter day" };

function todayLocal() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function isLateSameDayRequest(startDate) {
  if (startDate !== todayLocal()) return false;
  return new Date().getHours() >= SAME_DAY_CUTOFF_HOUR;
}

/**
 * Returns whether an employee is eligible for annual leave based on employment date.
 * If employment_date is missing → not eligible (default: don't show annual option).
 */
function isAnnualLeaveEligible(targetEmp) {
  if (!targetEmp?.employment_date) return false;
  const daysEmployed =
    (Date.now() - new Date(targetEmp.employment_date).getTime()) / (1000 * 60 * 60 * 24);
  return daysEmployed >= 180;
}

function daysEmployedCount(targetEmp) {
  if (!targetEmp?.employment_date) return 0;
  return Math.floor(
    (Date.now() - new Date(targetEmp.employment_date).getTime()) / (1000 * 60 * 60 * 24)
  );
}

function validateRequestSubmit({
  requestKind,
  employeeId,
  startDate,
  endDate,
  dayFraction,
  halfDay,
  actor,
  actorRole,
  targetEmp,
  forEmployeeId,
}) {
  const kind = String(requestKind || "annual").toLowerCase();
  const role = String(actorRole?.role || actorRole || "").toLowerCase();
  const empId = forEmployeeId || employeeId;
  const actorEmpId = actorRole?.employeeId || "";
  const isSelf =
    String(empId).toLowerCase() === String(actor || "").toLowerCase() ||
    (actorEmpId && String(empId) === String(actorEmpId));

  // --- Annual leave gate (all non-HR roles, not just agent) ---
  if (kind === "annual") {
    const isHrApprover = ["hr", "admin", "ceo"].includes(role);
    if (!isHrApprover) {
      // No employment date → annual leave not available
      if (!targetEmp?.employment_date) {
        throw new Error("Annual leave is not available — no employment date on record.");
      }
      const days = daysEmployedCount(targetEmp);
      if (days < 180) {
        throw new Error(
          `Annual leave requires 180+ days of employment. You have ${days} day(s).`
        );
      }
    }
    if (!isSelf && !["hr", "admin", "ceo"].includes(role)) {
      throw new Error("Annual leave can only be requested for yourself.");
    }
  }

  if (["unpaid", "medical", "same_day"].includes(kind) && ["tl", "op"].includes(role) && targetEmp) {
    if (targetEmp.team && actorRole?.team && targetEmp.team !== actorRole.team) {
      throw new Error("You can only request day off for agents on your team.");
    }
  }

  if (!startDate || !endDate) throw new Error("Start and end dates required.");
  if (endDate < startDate) throw new Error("End date must be on or after start date.");

  // --- Day fraction validation ---
  // Half-day / quarter-day only valid for single-day requests
  const fraction = dayFraction != null ? Number(dayFraction) : (halfDay ? 0.5 : 1);
  if (!VALID_FRACTIONS.includes(fraction)) {
    throw new Error(`Invalid day fraction. Allowed: ${VALID_FRACTIONS.join(", ")}`);
  }
  if (fraction < 1 && startDate !== endDate) {
    throw new Error("Half-day and quarter-day options are only available for single-day requests.");
  }

  return {
    requestKind: kind,
    lateSubmission: isLateSameDayRequest(startDate),
    paidLeave: kind === "annual",
    tlRequested: ["tl", "op"].includes(role) && !isSelf,
    dayFraction: fraction,
    halfDay: fraction === 0.5,
    quarterDay: fraction === 0.25,
  };
}

module.exports = {
  WORKDAY_START_HOUR,
  SAME_DAY_CUTOFF_HOUR,
  VALID_FRACTIONS,
  FRACTION_LABELS,
  isLateSameDayRequest,
  isAnnualLeaveEligible,
  daysEmployedCount,
  validateRequestSubmit,
};

