args.text:
(function () {
  "use strict";

  const IT_CATEGORIES = {
    hardware: "Hardware",
    software: "Software",
    network: "Network / Connectivity",
    account: "Account / Access",
    equipment: "Equipment",
    other: "Other",
  };

  const URGENCY_LABELS = {
    low: "Low",
    normal: "Normal",
    high: "High",
    critical: "Critical",
  };

  const URGENCY_BADGE = {
    low: "badge",
    normal: "badge badge-status",
    high: "badge badge-warn",
    critical: "badge badge-out",
  };

  const STATUS_LABELS = {
    open: "Open",
    in_progress: "In Progress",
    resolved: "Resolved",
    closed: "Closed",
  };

  const STATUS_BADGE = {
    open: "badge badge-warn",
    in_progress: "badge badge-ok",
    resolved: "badge badge-status",
    closed: "badge badge-out",
  };

  const esc = (s) =>
    String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

  async function renderItRequestsPage(root) {
    const canAssign   = state.user?.canAssignItRequest   === true;
    const canApprove  = state.user?.canApproveItRequest  === true;
    const canResolve  = state.user?.canResolveItRequest  === true;
    const canSubmit   = state.user?.canSubmitItRequest   === true;
    const myEmpId     = state.user?.employeeId || "";
    const myUsername  = state.user?.username || "";

    const statusFilter = new URLSearchParams(window.location.search).get("status") || "";
    const qs = statusFilter ? `?status=${statusFilter}` : "";
    const [data, itUsersData] = await Promise.all([
      api(`/it-requests${qs}`).catch(() => ({ requests: [] })),
      canAssign ? api("/it-requests/it-users").catch(() => ({ itUsers: [] })) : Promise.resolve({ itUsers: [] }),
    ]);
    const requests = data.requests || [];
    const itUsers  = itUsersData.itUsers || [];

    const statusTabs = ["", "open", "in_progress", "resolved", "closed"]
      .map((s) => `<button class="rules-tab${s === statusFilter ? " active" : ""}" data-it-status="${s}">${s ? STATUS_LABELS[s] : "All"}</button>`)
      .join("");

    root.innerHTML = `
      <style>
        .it-requests-tabs{display:flex;gap:.25rem;margin-bottom:1rem;flex-wrap:wrap}
        .it-grid{display:grid;grid-template-columns:1fr;gap:1rem}
        @media(min-width:768px){.it-grid{grid-template-columns:1fr 1fr}}
        .it-card{border:1px solid var(--border,#ddd);border-radius:6px;padding:.75rem}
        .it-card-header{display:flex;justify-content:space-between;align-items:flex-start;gap:.5rem;flex-wrap:wrap;margin-bottom:.5rem}
        .it-card-title{font-weight:600;margin:0}
        .it-card-meta{font-size:.8rem;color:var(--text-muted,#888)}
        .it-card-body{margin:.5rem 0;font-size:.9rem}
        .it-card-actions{display:flex;gap:.35rem;flex-wrap:wrap;margin-top:.5rem;align-items:center}
        .it-denial-reason{font-size:.85rem;color:var(--danger,#c00);margin-top:.25rem}
        .it-badge-routing{display:flex;gap:.25rem;flex-wrap:wrap;margin-top:.25rem}
      </style>
      <div class="page-header flex-between">
        <h1>IT Requests</h1>
        ${canSubmit ? '<button class="btn btn-primary btn-sm" id="it-new-request-btn">+ New Request</button>' : ""}
      </div>
      <div class="it-requests-tabs">${statusTabs}</div>
      ${requests.length === 0
        ? '<p class="muted">No IT requests found.</p>'
        : `<div class="it-grid">${requests.map((r) => renderItCard(r, { canAssign, canApprove, canResolve, myEmpId, itUsers })).join("")}</div>`}
    `;

    root.querySelectorAll("[data-it-status]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const s = btn.dataset.itStatus;
        window.history.pushState({}, "", s ? `?page=it-requests&status=${s}` : "?page=it-requests");
        renderItRequestsPage(root);
      });
    });

    root.querySelector("#it-new-request-btn")?.addEventListener("click", () =>
      openNewItRequestModal(root, myEmpId)
    );

    // Assign dropdown
    root.querySelectorAll("[data-it-assign-sel]").forEach((sel) => {
      sel.addEventListener("change", async () => {
        const id = sel.dataset.itAssignSel;
        const assignedTo = sel.value;
        if (!assignedTo) return;
        try {
          await api(`/it-requests/${id}`, {
            method: "PATCH",
            body: JSON.stringify({ assignedTo }),
          });
          renderItRequestsPage(root);
        } catch (e) { alert(e.message); }
      });
    });

    // Reassign button
    root.querySelectorAll("[data-it-reassign]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const id = btn.dataset.itReassign;
        openReassignModal(id, itUsers, () => renderItRequestsPage(root));
      });
    });

    // Approve
    root.querySelectorAll("[data-it-approve]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        if (!confirm("Approve this IT request and mark it In Progress?")) return;
        try {
          await api(`/it-requests/${btn.dataset.itApprove}`, {
            method: "PATCH",
            body: JSON.stringify({ action: "approve" }),
          });
          renderItRequestsPage(root);
        } catch (e) { alert(e.message); }
      });
    });

    // Deny
    root.querySelectorAll("[data-it-deny]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const reason = prompt("Reason for denying this request (optional):");
        try {
          await api(`/it-requests/${btn.dataset.itDeny}`, {
            method: "PATCH",
            body: JSON.stringify({ action: "deny", denialReason: reason || "" }),
          });
          renderItRequestsPage(root);
        } catch (e) { alert(e.message); }
      });
    });

    // Resolve
    root.querySelectorAll("[data-it-resolve]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const notes = prompt("Resolution notes (optional):");
        try {
          await api(`/it-requests/${btn.dataset.itResolve}`, {
            method: "PATCH",
            body: JSON.stringify({ status: "resolved", resolutionNotes: notes || "" }),
          });
          renderItRequestsPage(root);
        } catch (e) { alert(e.message); }
      });
    });

    // Reopen
    root.querySelectorAll("[data-it-reopen]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        try {
          await api(`/it-requests/${btn.dataset.itReopen}`, {
            method: "PATCH",
            body: JSON.stringify({ status: "open" }),
          });
          renderItRequestsPage(root);
        } catch (e) { alert(e.message); }
      });
    });
  }

  function renderItCard(r, { canAssign, canApprove, canResolve, myEmpId, itUsers }) {
    const isOpen       = r.status === "open";
    const isInProgress = r.status === "in_progress";
    const isDone       = r.status === "resolved" || r.status === "closed";

    const actions = [];

    if (canApprove && isOpen) {
      actions.push(`<button class="btn btn-sm btn-primary" data-it-approve="${r.id}">Approve</button>`);
      actions.push(`<button class="btn btn-sm btn-danger"  data-it-deny="${r.id}">Deny</button>`);
    }

    if (canAssign && (isOpen || isInProgress)) {
      const opts = itUsers
        .map((u) => `<option value="${esc(u.username)}" ${r.assignedTo === u.username ? "selected" : ""}>${esc(u.displayName || u.username)}</option>`)
        .join("");
      actions.push(`<select data-it-assign-sel="${r.id}" style="max-width:11rem;font-size:.8rem">
        <option value="">Assign to…</option>
        ${opts}
      </select>`);
      if (r.assignedTo) {
        actions.push(`<button class="btn btn-sm" data-it-reassign="${r.id}">Reassign</button>`);
      }
    }

    if (canResolve && (isOpen || isInProgress)) {
      actions.push(`<button class="btn btn-sm" data-it-resolve="${r.id}">Resolve</button>`);
    }

    if (isDone) {
      actions.push(`<button class="btn btn-sm" data-it-reopen="${r.id}">Reopen</button>`);
    }

    const routingBadges = [];
    if (r.approvedBy)   routingBadges.push(`<span class="badge badge-ok">Approved by ${esc(r.approvedBy)}</span>`);
    if (r.deniedBy)     routingBadges.push(`<span class="badge badge-out">Denied by ${esc(r.deniedBy)}</span>`);
    if (r.reassignedBy) routingBadges.push(`<span class="badge badge-status">Reassigned by ${esc(r.reassignedBy)}</span>`);

    return `<div class="it-card">
      <div class="it-card-header">
        <div>
          <div class="it-card-title">${esc(r.title)}</div>
          <div class="it-card-meta">
            #${(r.id || "").slice(0, 8)} &middot; ${esc(IT_CATEGORIES[r.category] || r.category)}
            &middot; <span class="${URGENCY_BADGE[r.urgency] || "badge"}">${esc(URGENCY_LABELS[r.urgency] || r.urgency)}</span>
            ${r.unit ? `&middot; Unit: ${esc(r.unit)}` : ""}
          </div>
        </div>
        <span class="${STATUS_BADGE[r.status] || "badge"}">${STATUS_LABELS[r.status] || r.status}</span>
      </div>
      ${r.description ? `<div class="it-card-body">${esc(r.description)}</div>` : ""}
      <div class="it-card-meta">
        From: ${esc(r.employeeId)} &middot;
        Assigned: ${r.assignedTo ? esc(r.assignedTo) : '<em>Unassigned</em>'} &middot;
        ${r.createdAt ? new Date(r.createdAt).toLocaleDateString() : ""}
      </div>
      ${routingBadges.length ? `<div class="it-badge-routing">${routingBadges.join("")}</div>` : ""}
      ${r.denialReason ? `<div class="it-denial-reason">Denial reason: ${esc(r.denialReason)}</div>` : ""}
      ${r.resolutionNotes ? `<div class="it-card-body" style="color:var(--text-muted,#888);font-size:.85rem">Resolution: ${esc(r.resolutionNotes)}</div>` : ""}
      ${actions.length ? `<div class="it-card-actions">${actions.join("")}</div>` : ""}
    </div>`;
  }

  function openReassignModal(requestId, itUsers, onDone) {
    const opts = itUsers
      .map((u) => `<option value="${esc(u.username)}">${esc(u.displayName || u.username)}</option>`)
      .join("");
    const html = `
      <div class="modal-header"><h2>Reassign IT Request</h2><button class="btn btn-sm" data-close>✕</button></div>
      <div class="modal-body">
        <label class="field"><span>Assign to</span>
          <select id="it-reassign-sel">${opts}</select>
        </label>
      </div>
      <div class="modal-footer">
        <button class="btn" data-close>Cancel</button>
        <button class="btn btn-primary" id="it-reassign-confirm">Reassign</button>
      </div>`;
    window.openModal(html);
    document.getElementById("it-reassign-confirm").onclick = async () => {
      const assignedTo = document.getElementById("it-reassign-sel").value;
      if (!assignedTo) return alert("Select a user");
      try {
        await api(`/it-requests/${requestId}`, {
          method: "PATCH",
          body: JSON.stringify({ action: "reassign", assignedTo }),
        });
        window.closeModal();
        onDone();
      } catch (e) { alert(e.message); }
    };
  }

  function openNewItRequestModal(root, myEmpId) {
    const catOpts = Object.entries(IT_CATEGORIES)
      .map(([k, v]) => `<option value="${k}">${v}</option>`).join("");
    const urgOpts = Object.entries(URGENCY_LABELS)
      .map(([k, v]) => `<option value="${k}" ${k === "normal" ? "selected" : ""}>${v}</option>`).join("");

    const html = `
      <div class="modal-header"><h2>New IT Request</h2><button class="btn btn-sm" data-close>✕</button></div>
      <form id="it-new-form" class="modal-body field-grid">
        <label class="field"><span>Employee ID</span>
          <input name="employeeId" value="${esc(myEmpId)}" required /></label>
        <label class="field"><span>Title</span><input name="title" required /></label>
        <label class="field"><span>Category</span><select name="category">${catOpts}</select></label>
        <label class="field"><span>Urgency</span><select name="urgency">${urgOpts}</select></label>
        <label class="field" style="grid-column:1/-1">
          <span>Description (optional)</span>
          <textarea name="description" rows="3"></textarea>
        </label>
      </form>
      <div class="modal-footer">
        <button class="btn" data-close>Cancel</button>
        <button class="btn btn-primary" id="it-new-submit">Submit</button>
      </div>`;

    window.openModal(html);
    document.getElementById("it-new-submit").onclick = async () => {
      const form = document.getElementById("it-new-form");
      const fd = new FormData(form);
      const body = {
        employeeId: String(fd.get("employeeId") || "").trim(),
        title: String(fd.get("title") || "").trim(),
        category: fd.get("category") || "other",
        urgency: fd.get("urgency") || "normal",
        description: String(fd.get("description") || "").trim(),
      };
      if (!body.employeeId || !body.title) return alert("Employee ID and title are required");
      try {
        await api("/it-requests", { method: "POST", body: JSON.stringify(body) });
        window.closeModal();
        renderItRequestsPage(root);
      } catch (e) { alert(e.message); }
    };
  }

  window.ItRequestsModule = { renderItRequestsPage };
})();

/**
 * Unified Requests — annual, unpaid, medical, same-day off.
 * Supports half-day (0.5) and quarter-day (0.25) fractions.
 * Annual leave is hidden when the employee has no employment_date or < 180 days.
 */
window.RequestsModule = (function () {
  const KIND_LABELS = {
    annual:   "Annual leave (paid)",
    unpaid:   "Unpaid day off",
    medical:  "Medical / sick",
    same_day: "Same-day off",
  };

  const FRACTION_LABELS = {
    "1":    "Full day",
    "0.5":  "Half day",
    "0.25": "Quarter day",
  };

  function canApprove(data) {
    return data?.canApprove === true;
  }

  function isHrRole() {
    return ["hr", "admin", "ceo"].includes(state.user?.role);
  }

  function canSubmitForOthers() {
    return isHrRole() || ["tl", "op"].includes(state.user?.role);
  }

  /**
   * Returns true if this employee is eligible for annual leave.
   * No employment_date → false (hide annual option).
   * < 180 days → false.
   */
  function annualEligible(emp) {
    if (!emp || !emp.employment_date) return false;
    const days = (Date.now() - new Date(emp.employment_date).getTime()) / (1000 * 60 * 60 * 24);
    return days >= 180;
  }

  function kindBadge(r) {
    const kind = r.requestKind || r.leaveType || "annual";
    const late = r.lateSubmission  ? ' <span class="badge badge-warn">Late</span>' : "";
    const tl   = r.requestedBy && r.requestedBy !== r.employeeId
      ? ' <span class="badge badge-warn">TL/OP</span>' : "";
    const paid = r.paidLeave ? ' <span class="badge badge-ok">Paid</span>' : "";
    const frac = Number(r.dayFraction || 1);
    const fracBadge = frac < 1
      ? ` <span class="badge badge-status">${FRACTION_LABELS[String(frac)] || frac + "d"}</span>`
      : "";
    return `${KIND_LABELS[kind] || kind}${paid}${fracBadge}${late}${tl}`;
  }

  async function renderRequestsPage(root, api, state, helpers) {
    const { escapeHtml, openModal, closeModal, employeeSelectOptions } = helpers;
    const empQ = typeof employeesQuery === "function" ? employeesQuery() : "";
    const [data, empData] = await Promise.all([
      api("/hrms/leave"),
      api(`/employees${empQ}`).catch(() => ({ employees: [] })),
    ]);
    let employees = empData.employees || [];
    let requests  = data.requests  || [];
    const selfId  = state.user?.employeeId || state.user?.username || "";

    if (!canSubmitForOthers() && selfId) {
      requests  = requests.filter((r) => String(r.employeeId).toLowerCase() === String(selfId).toLowerCase());
      employees = employees.filter((e) => String(e.id).toLowerCase() === String(selfId).toLowerCase());
    } else if (["tl", "op"].includes(state.user?.role) && state.user?.team) {
      const teamIds = new Set(employees.filter((e) => e.team === state.user.team).map((e) => e.id));
      if (!isHrRole()) {
        requests = requests.filter((r) => teamIds.has(r.employeeId) || r.employeeId === selfId);
      }
    }

    const empName = (id) => {
      const e = employees.find((x) => x.id === id);
      return e ? escapeHtml(e.american_name || e.id) : escapeHtml(id);
    };

    root.innerHTML = `
      <div class="page-header flex-between">
        <div>
          <h1>Requests</h1>
          <p class="muted">Annual, unpaid, medical, and same-day off &middot; Approvers: Mark, Raymond, Phoebe</p>
        </div>
        <button class="btn btn-primary" id="new-request-btn">+ New request</button>
      </div>
      <div class="table-wrap card"><table>
        <thead><tr>
          <th>Employee</th><th>Dates</th><th>Type</th><th>Status</th><th>Notes</th><th></th>
        </tr></thead>
        <tbody>${requests.length ? requests.map((r) => `<tr>
          <td>${empName(r.employeeId)}<br><span class="muted">${escapeHtml(r.employeeId)}</span></td>
          <td>${r.startDate}${r.startDate !== r.endDate ? " – " + r.endDate : ""}
            ${Number(r.dayFraction || 1) < 1
              ? `<br><span class="muted">${FRACTION_LABELS[String(r.dayFraction)] || ""}</span>`
              : ""}
          </td>
          <td>${kindBadge(r)}</td>
          <td><span class="badge">${escapeHtml(r.status)}</span></td>
          <td>${escapeHtml(r.notes || "")}</td>
          <td class="btn-row">
            ${canApprove(data) && r.status === "pending" ? `
              <button class="btn btn-sm btn-primary" data-approve="${r.id}">Approve</button>
              <button class="btn btn-sm" data-reject="${r.id}">Reject</button>` : ""}
            ${canApprove(data) ? `
              <button class="btn btn-sm" data-edit="${r.id}">Edit</button>
              <button class="btn btn-sm btn-danger" data-delete="${r.id}">Delete</button>` : ""}
          </td>
        </tr>`).join("") : '<tr><td colspan="6" class="muted">No requests</td></tr>'}
        </tbody>
      </table></div>`;

    const refresh = () => renderRequestsPage(root, api, state, helpers);

    root.querySelector("#new-request-btn").onclick = () =>
      openRequestModal({ api, employees, selfId, openModal, closeModal, employeeSelectOptions, escapeHtml, onDone: refresh });

    root.querySelectorAll("[data-approve]").forEach((b) => {
      b.onclick = async () => {
        await api(`/hrms/leave/${b.dataset.approve}`, { method: "PUT", body: JSON.stringify({ status: "approved" }) });
        refresh();
      };
    });
    root.querySelectorAll("[data-reject]").forEach((b) => {
      b.onclick = async () => {
        await api(`/hrms/leave/${b.dataset.reject}`, { method: "PUT", body: JSON.stringify({ status: "rejected" }) });
        refresh();
      };
    });
    root.querySelectorAll("[data-delete]").forEach((b) => {
      b.onclick = async () => {
        if (!confirm("Delete this request? Approved attendance will be cleared.")) return;
        await api(`/hrms/leave/${b.dataset.delete}`, { method: "DELETE" });
        refresh();
      };
    });
    root.querySelectorAll("[data-edit]").forEach((b) => {
      b.onclick = () => {
        const r = requests.find((x) => String(x.id) === b.dataset.edit);
        if (r) openRequestModal({ api, employees, selfId, request: r, openModal, closeModal, employeeSelectOptions, escapeHtml, onDone: refresh });
      };
    });
  }

  function openRequestModal({ api, employees, selfId, request, openModal, closeModal, employeeSelectOptions, escapeHtml, onDone }) {
    const isEdit    = !!request;
    const forOthers = canSubmitForOthers();
    const agentList = forOthers ? employees : employees.filter((e) => e.id === selfId);
    const defaultEmpId = request?.employeeId || selfId || (agentList[0]?.id || "");

    // Determine annual eligibility for the default employee (may change on select)
    function getEmpById(id) {
      return agentList.find((e) => String(e.id).toLowerCase() === String(id || "").toLowerCase()) || null;
    }
    const defaultEmp   = getEmpById(defaultEmpId);
    const hrRole       = isHrRole();
    // HR/admin/ceo can always choose annual; others need 180+ days and an employment_date
    const canAnnual    = hrRole || annualEligible(defaultEmp);
    const daysEmployed = defaultEmp?.employment_date
      ? Math.floor((Date.now() - new Date(defaultEmp.employment_date).getTime()) / (1000 * 60 * 60 * 24))
      : null;

    const annualOpt = canAnnual
      ? `<option value="annual" ${(request?.requestKind || request?.leaveType) === "annual" ? "selected" : ""}>Annual leave (paid)</option>`
      : "";
    const annualNote = !hrRole && daysEmployed !== null && daysEmployed < 180
      ? `<p class="muted" style="grid-column:1/-1;color:var(--warn,#a05000)">Annual leave requires 180+ days of employment (${daysEmployed} day${daysEmployed !== 1 ? "s" : ""} so far).</p>`
      : (!hrRole && daysEmployed === null
        ? `<p class="muted" style="grid-column:1/-1;color:var(--warn,#a05000)">Annual leave is unavailable — no employment date on record.</p>`
        : "");

    const curFrac = String(request?.dayFraction ?? 1);
    const isSingleDay = request ? (request.startDate === request.endDate) : true;

    openModal(`
      <div class="modal-header">
        <h2>${isEdit ? "Edit request" : "New request"}</h2>
        <button class="btn btn-sm" data-close>✕</button>
      </div>
      <form id="request-form" class="modal-body field-grid modal-body-scroll">
        <label class="field"><span>Employee</span>
          <select name="employeeId" id="req-emp" required ${!forOthers ? "disabled" : ""}>
            ${employeeSelectOptions(agentList, defaultEmpId)}
          </select>
        </label>
        ${!forOthers ? `<input type="hidden" name="employeeId" value="${escapeHtml(defaultEmpId)}" />` : ""}
        ${annualNote}
        <label class="field"><span>Request type</span>
          <select name="requestKind" id="req-kind">
            ${annualOpt}
            <option value="unpaid"   ${(request?.requestKind || request?.leaveType) === "unpaid"   ? "selected" : ""}>Unpaid day off</option>
            <option value="medical"  ${(request?.requestKind || request?.leaveType) === "medical"  ? "selected" : ""}>Medical / sick</option>
            <option value="same_day" ${(request?.requestKind || request?.leaveType) === "same_day" ? "selected" : ""}>Same-day off</option>
          </select>
        </label>
        <label class="field"><span>Start date</span>
          <input name="startDate" type="date" required value="${request?.startDate || ""}" id="req-start" />
        </label>
        <label class="field"><span>End date</span>
          <input name="endDate" type="date" required value="${request?.endDate || ""}" id="req-end" />
        </label>
        <label class="field" id="req-fraction-wrap">
          <span>Duration</span>
          <select name="dayFraction" id="req-fraction">
            <option value="1"    ${curFrac === "1"    ? "selected" : ""}>Full day</option>
            <option value="0.5"  ${curFrac === "0.5"  ? "selected" : ""}>Half day</option>
            <option value="0.25" ${curFrac === "0.25" ? "selected" : ""}>Quarter day (2 hours)</option>
          </select>
        </label>
        <label class="field" style="grid-column:1/-1">
          <span>Notes</span>
          <textarea name="notes">${escapeHtml(request?.notes || "")}</textarea>
        </label>
        <p class="muted" style="grid-column:1/-1">
          Same-day requests after 12:00 are allowed but flagged as late. Workday starts 3 PM.
          Half-day and quarter-day options apply to single-day requests only.
        </p>
      </form>
      <div class="modal-footer">
        <button class="btn" data-close>Cancel</button>
        <button class="btn btn-primary" id="submit-request">${isEdit ? "Save" : "Submit"}</button>
      </div>`, true);

    // Hide fraction picker when multi-day range is selected
    function updateFractionVisibility() {
      const start = document.getElementById("req-start")?.value;
      const end   = document.getElementById("req-end")?.value;
      const wrap  = document.getElementById("req-fraction-wrap");
      if (!wrap) return;
      wrap.style.display = (start && end && start !== end) ? "none" : "";
      if (start && end && start !== end) {
        const sel = document.getElementById("req-fraction");
        if (sel) sel.value = "1";
      }
    }
    document.getElementById("req-start")?.addEventListener("change", updateFractionVisibility);
    document.getElementById("req-end")?.addEventListener("change", updateFractionVisibility);
    // Also sync end date to start for same-day if no end yet
    document.getElementById("req-start")?.addEventListener("change", () => {
      const startEl = document.getElementById("req-start");
      const endEl   = document.getElementById("req-end");
      if (endEl && !endEl.value) endEl.value = startEl.value;
      updateFractionVisibility();
    });
    updateFractionVisibility();

    document.getElementById("submit-request").onclick = async () => {
      const fd = new FormData(document.getElementById("request-form"));
      const body = Object.fromEntries(fd.entries());
      if (!forOthers) body.employeeId = defaultEmpId;
      body.leaveType    = body.requestKind;
      body.dayFraction  = Number(body.dayFraction || 1);
      body.halfDay      = body.dayFraction === 0.5;
      body.quarterDay   = body.dayFraction === 0.25;
      try {
        if (isEdit) {
          await api(`/hrms/leave/${request.id}`, { method: "PUT",  body: JSON.stringify(body) });
        } else {
          await api("/hrms/leave",                { method: "POST", body: JSON.stringify(body) });
        }
        closeModal();
        onDone();
      } catch (e) {
        alert(e.message);
      }
    };
  }

  return { renderRequestsPage };
})();

(function () {
  "use strict";

  const STATUS_LABELS = {
    pending:     "Pending",
    approved:    "Approved",
    rejected:    "Rejected",
    rescheduled: "Rescheduled",
  };

  const STATUS_BADGE = {
    pending:     "badge badge-warn",
    approved:    "badge badge-ok",
    rejected:    "badge badge-out",
    rescheduled: "badge badge-status",
  };

  const esc = (s) =>
    String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

  /** ── Participant helpers ──────────────────────────────────────────────── */

  /**
   * Parse stored participant strings:
   *   "employee:HS1-001"  → individual
   *   "team:HS-1|Team A"  → whole team
   *   "unit:HS-1"         → whole unit
   *   legacy bare ID      → individual
   */
  function parseParticipant(p) {
    const s = String(p || "");
    if (s.startsWith("employee:")) return { type: "employee", value: s.slice(9) };
    if (s.startsWith("team:"))     {
      const [u, t] = s.slice(5).split("|");
      return { type: "team", unit: u || "", team: t || "" };
    }
    if (s.startsWith("unit:"))     return { type: "unit", value: s.slice(5) };
    return { type: "employee", value: s }; // legacy bare id
  }

  function participantLabel(p, empName) {
    const parsed = parseParticipant(p);
    if (parsed.type === "unit")     return `🏢 Whole unit: ${parsed.value}`;
    if (parsed.type === "team")     return `👥 Team: ${[parsed.unit, parsed.team].filter(Boolean).join(" / ")}`;
    return empName(parsed.value);
  }

  /** Returns participant scope options available to the current user */
  function buildParticipantOptions(role, leadTeams, employees, orgTeams) {
    const isHrAdmin = ["hr", "admin", "ceo"].includes(role);
    const isOp      = role === "op";
    const isTl      = role === "tl";
    const myUnit    = state.user?.unit || "";

    const options = {
      employees: [],  // { value, label }
      teams:     [],  // { value, label }
      units:     [],  // { value, label }
    };

    // ── Employees ──
    // TL sees their own team; OP sees their unit; HR/Admin see all
    let visibleEmps = employees;
    if (isTl) {
      const myTeamNames = new Set((leadTeams || []).map((lt) => lt.team));
      visibleEmps = employees.filter((e) => myTeamNames.has(e.team));
    } else if (isOp && myUnit) {
      visibleEmps = employees.filter((e) => e.unit === myUnit);
    }
    options.employees = visibleEmps.map((e) => ({
      value: `employee:${e.id}`,
      label: e.american_name || e.arabic_name || e.id,
    }));

    // ── Teams ──
    let visibleTeams = orgTeams || [];
    if (isTl) {
      const allowed = new Set((leadTeams || []).map((lt) => `${lt.unit}|${lt.team}`));
      visibleTeams = visibleTeams.filter((t) => allowed.has(`${t.unit}|${t.name}`));
    } else if (isOp && myUnit) {
      visibleTeams = visibleTeams.filter((t) => t.unit === myUnit);
    }
    options.teams = visibleTeams.map((t) => ({
      value: `team:${t.unit}|${t.name}`,
      label: `Team: ${[t.unit, t.name].filter(Boolean).join(" / ")}`,
    }));

    // ── Units (OP and above only) ──
    if (isOp || isHrAdmin) {
      const units = [...new Set(employees.map((e) => e.unit).filter(Boolean))];
      const allowedUnits = isOp ? [myUnit] : units;
      options.units = allowedUnits.map((u) => ({
        value: `unit:${u}`,
        label: `Whole unit: ${u}`,
      }));
    }

    return options;
  }

  /** ── Page renderer ────────────────────────────────────────────────────── */

  async function renderMeetingRequestsPage(root) {
    const canReview = state.user?.canReviewMeetingRequest === true;
    const canSubmit = state.user?.canSubmitMeetingRequest === true;
    const role      = state.user?.role || "";
    const leadTeams = state.user?.leadTeams || [];

    const statusFilter = new URLSearchParams(window.location.search).get("status") || "";
    const qs = statusFilter ? `?status=${statusFilter}` : "";

    const [data, empData, teamsData] = await Promise.all([
      api(`/meeting-requests${qs}`).catch(() => ({ requests: [] })),
      api("/employees").catch(() => ({ employees: [] })),
      api("/hrms/teams").catch(() => ({ teams: [] })),
    ]);
    const requests  = data.requests  || [];
    const employees = empData.employees || (state.meta?.employees || []);
    const orgTeams  = teamsData.teams || [];

    function empName(id) {
      const e = employees.find((x) => x.id === id);
      return e ? (e.american_name || e.arabic_name || e.id) : (id || "—");
    }

    const statusTabs = ["", "pending", "approved", "rejected", "rescheduled"]
      .map((s) => `<button class="rules-tab${s === statusFilter ? " active" : ""}" data-mr-status="${s}">${s ? STATUS_LABELS[s] : "All"}</button>`)
      .join("");

    root.innerHTML = `
      <style>
        .mr-grid{display:grid;grid-template-columns:1fr;gap:1rem}
        @media(min-width:768px){.mr-grid{grid-template-columns:1fr 1fr}}
        .mr-card{border:1px solid var(--border,#ddd);border-radius:6px;padding:.75rem}
        .mr-card-header{display:flex;justify-content:space-between;align-items:flex-start;gap:.5rem;flex-wrap:wrap;margin-bottom:.5rem}
        .mr-card-title{font-weight:600;margin:0}
        .mr-card-meta{font-size:.8rem;color:var(--text-muted,#888)}
        .mr-card-body{margin:.5rem 0;font-size:.9rem}
        .mr-card-actions{display:flex;gap:.35rem;flex-wrap:wrap;margin-top:.5rem}
        .mr-participants{font-size:.85rem;margin-top:.35rem}
        .mr-participants-list{list-style:none;padding:0;margin:.25rem 0 0}
        .mr-participants-list li{padding:.1rem 0}
      </style>
      <div class="page-header flex-between">
        <h1>Meeting Requests</h1>
        ${canSubmit ? '<button class="btn btn-primary btn-sm" id="mr-new-btn">+ New Request</button>' : ""}
      </div>
      <div style="display:flex;gap:.25rem;margin-bottom:1rem;flex-wrap:wrap">${statusTabs}</div>
      ${requests.length === 0
        ? '<p class="muted">No meeting requests found.</p>'
        : `<div class="mr-grid">${requests.map((r) => renderCard(r, { canReview, empName })).join("")}</div>`}
    `;

    root.querySelectorAll("[data-mr-status]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const s = btn.dataset.mrStatus;
        window.history.pushState({}, "", s ? `?page=meeting-requests&status=${s}` : "?page=meeting-requests");
        renderMeetingRequestsPage(root);
      });
    });

    root.querySelector("#mr-new-btn")?.addEventListener("click", () =>
      openNewMrModal(root, { role, leadTeams, employees, orgTeams })
    );

    root.querySelectorAll("[data-mr-approve]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        if (!confirm("Approve this meeting request?")) return;
        try {
          await api(`/meeting-requests/${btn.dataset.mrApprove}`, {
            method: "PATCH",
            body: JSON.stringify({ status: "approved" }),
          });
          renderMeetingRequestsPage(root);
        } catch (e) { alert(e.message); }
      });
    });

    root.querySelectorAll("[data-mr-reject]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const notes = prompt("Rejection reason (optional):");
        try {
          await api(`/meeting-requests/${btn.dataset.mrReject}`, {
            method: "PATCH",
            body: JSON.stringify({ status: "rejected", reviewNotes: notes || "" }),
          });
          renderMeetingRequestsPage(root);
        } catch (e) { alert(e.message); }
      });
    });
  }

  function renderCard(r, { canReview, empName }) {
    const dateStr = r.proposedDate
      ? new Date(r.proposedDate + "T" + (r.proposedTime || "00:00")).toLocaleString()
      : "—";

    const participantItems = (r.participants || [])
      .map((p) => `<li>${esc(participantLabel(p, empName))}</li>`)
      .join("");

    let actions = "";
    if (canReview && r.status === "pending") {
      actions = `<button class="btn btn-sm btn-primary" data-mr-approve="${r.id}">Approve</button>
        <button class="btn btn-sm btn-danger" data-mr-reject="${r.id}">Reject</button>`;
    }

    return `<div class="mr-card">
      <div class="mr-card-header">
        <div>
          <div class="mr-card-title">${esc(r.title)}</div>
          <div class="mr-card-meta">By ${esc(empName(r.requesterEmployeeId))} &middot; ${r.durationMinutes} min</div>
        </div>
        <span class="${STATUS_BADGE[r.status] || "badge"}">${STATUS_LABELS[r.status] || r.status}</span>
      </div>
      ${r.description ? `<div class="mr-card-body">${esc(r.description)}</div>` : ""}
      <div class="mr-card-meta">Proposed: ${esc(dateStr)}</div>
      ${participantItems ? `<div class="mr-participants"><strong>Participants:</strong><ul class="mr-participants-list">${participantItems}</ul></div>` : ""}
      ${r.reviewNotes ? `<div class="mr-card-meta" style="margin-top:.35rem">Review note: ${esc(r.reviewNotes)}</div>` : ""}
      ${actions ? `<div class="mr-card-actions">${actions}</div>` : ""}
    </div>`;
  }

  /** ── New meeting request modal ────────────────────────────────────────── */

  function openNewMrModal(root, { role, leadTeams, employees, orgTeams }) {
    const myId   = state.user?.employeeId || "";
    const opts   = buildParticipantOptions(role, leadTeams, employees, orgTeams);
    const isHrAdmin = ["hr", "admin", "ceo"].includes(role);
    const isOp      = role === "op";
    const isTl      = role === "tl";

    // Build participant sections
    function buildSection(title, items, groupName) {
      if (!items.length) return "";
      return `<div class="mr-picker-group">
        <div class="mr-picker-group-label">${title}</div>
        ${items.map((it) => `<label class="mr-picker-item">
          <input type="checkbox" name="${groupName}" value="${esc(it.value)}" />
          ${esc(it.label)}
        </label>`).join("")}
      </div>`;
    }

    const participantHtml = `
      ${buildSection("Individual Employees", opts.employees, "participant")}
      ${buildSection("Whole Team", opts.teams, "participant")}
      ${buildSection("Whole Unit", opts.units, "participant")}
    `;

    const html = `
      <div class="modal-header"><h2>New Meeting Request</h2><button class="btn btn-sm" data-close>✕</button></div>
      <style>
        .mr-picker-group{margin-bottom:.75rem}
        .mr-picker-group-label{font-weight:600;font-size:.8rem;text-transform:uppercase;color:var(--text-muted,#888);margin-bottom:.25rem}
        .mr-picker-item{display:flex;align-items:center;gap:.35rem;font-size:.9rem;padding:.2rem 0;cursor:pointer}
        .mr-picker-scroll{max-height:220px;overflow-y:auto;border:1px solid var(--border,#ddd);border-radius:4px;padding:.5rem}
        .mr-picker-search{width:100%;margin-bottom:.5rem;font-size:.85rem;padding:.3rem .5rem;box-sizing:border-box}
      </style>
      <form id="mr-new-form" class="modal-body field-grid modal-body-scroll">
        <label class="field"><span>Title</span><input name="title" required /></label>
        <label class="field"><span>Description (optional)</span><textarea name="description" rows="2"></textarea></label>
        <label class="field"><span>Date</span>
          <input name="proposedDate" type="date" value="${new Date().toISOString().slice(0, 10)}" required />
        </label>
        <label class="field"><span>Time</span>
          <input name="proposedTime" type="time" value="10:00" required />
        </label>
        <label class="field"><span>Duration (minutes)</span>
          <input name="durationMinutes" type="number" value="30" min="5" />
        </label>
        <input name="requesterEmployeeId" type="hidden" value="${esc(myId)}" />
        <input name="requesterRole"       type="hidden" value="${esc(role)}" />
        <div class="field" style="grid-column:1/-1">
          <span style="font-weight:600">Participants <span class="muted">(select employees, teams, or units)</span></span>
          <input type="text" class="mr-picker-search" id="mr-picker-search" placeholder="Search…" />
          <div class="mr-picker-scroll" id="mr-picker-container">
            ${participantHtml || '<p class="muted">No participants available.</p>'}
          </div>
          <div id="mr-selected-summary" style="margin-top:.4rem;font-size:.85rem;color:var(--text-muted,#888)"></div>
        </div>
      </form>
      <div class="modal-footer">
        <button class="btn" data-close>Cancel</button>
        <button class="btn btn-primary" id="mr-submit-btn">Submit</button>
      </div>`;

    window.openModal(html);

    // Live search filter
    document.getElementById("mr-picker-search")?.addEventListener("input", (e) => {
      const q = e.target.value.toLowerCase();
      document.querySelectorAll("#mr-picker-container .mr-picker-item").forEach((el) => {
        el.style.display = !q || el.textContent.toLowerCase().includes(q) ? "" : "none";
      });
    });

    // Selection summary counter
    function updateSummary() {
      const checked = Array.from(document.querySelectorAll('#mr-new-form input[name="participant"]:checked'));
      const el = document.getElementById("mr-selected-summary");
      if (el) el.textContent = checked.length ? `${checked.length} participant(s) selected` : "";
    }
    document.getElementById("mr-picker-container")?.addEventListener("change", updateSummary);

    document.getElementById("mr-submit-btn").onclick = async () => {
      const form = document.getElementById("mr-new-form");
      const fd   = new FormData(form);
      const participants = Array.from(form.querySelectorAll('input[name="participant"]:checked')).map((el) => el.value);

      if (!participants.length) {
        return alert("Please select at least one participant, team, or unit.");
      }

      const body = {
        title:                String(fd.get("title") || "").trim(),
        description:          String(fd.get("description") || "").trim(),
        proposedDate:         fd.get("proposedDate"),
        proposedTime:         fd.get("proposedTime"),
        durationMinutes:      Number(fd.get("durationMinutes")) || 30,
        requesterEmployeeId:  String(fd.get("requesterEmployeeId") || "").trim(),
        requesterRole:        String(fd.get("requesterRole") || ""),
        participants,
      };

      if (!body.title || !body.proposedDate || !body.proposedTime || !body.requesterEmployeeId) {
        return alert("Title, date, time, and employee ID are required");
      }

      try {
        await api("/meeting-requests", { method: "POST", body: JSON.stringify(body) });
        window.closeModal();
        renderMeetingRequestsPage(root);
      } catch (e) { alert(e.message); }
    };
  }

  window.MeetingRequestsModule = { renderMeetingRequestsPage };
})();
